import { ROLE_SHORTCUT_LIMITS, type PlanName } from "@/lib/plans";

export const PRESET_ROLES = [
  "Software Engineer Intern",
  "Frontend Developer",
  "Backend Developer",
  "Full Stack Developer",
  "Software Engineer",
];
export const commonRoles = PRESET_ROLES;

export function normalizeRole(title: string): string {
  return title.trim().replace(/\s+/g, " ").toLowerCase();
}

export function isPresetRole(title: string): boolean {
  return PRESET_ROLES.some(
    (role) => normalizeRole(role) === normalizeRole(title),
  );
}
export const isCanonicalRole = isPresetRole;

export function getRoleShortcutLimit(plan: PlanName): number {
  return ROLE_SHORTCUT_LIMITS[plan === "PAID" ? "premium" : "free"];
}

export function roleShortcutHelp(plan: PlanName): string {
  return `Save up to ${getRoleShortcutLimit(plan)} role shortcuts with any role text. Contact job roles are unrestricted. Existing shortcuts can be kept or removed.`;
}

export function roleShortcutError(
  plan: PlanName,
  titles: readonly string[],
  existing: readonly string[],
): string | undefined {
  const limit = getRoleShortcutLimit(plan);
  if (titles.length <= limit) return;
  const saved = new Set(existing.map(normalizeRole));
  if (
    titles.length <= existing.length &&
    titles.every((title) => saved.has(normalizeRole(title)))
  )
    return;
  return `Save at most ${limit} role shortcuts. Existing shortcuts can be kept or removed.`;
}

export function distinctCustomRoles(titles: readonly string[]): string[] {
  return [
    ...new Set(
      titles
        .map(normalizeRole)
        .filter((title) => title && !isPresetRole(title)),
    ),
  ];
}

export type RoleUsage = {
  shortcuts: string[];
  contactRoles: {
    title: string;
    count: number;
    contacts: { id: string; name: string }[];
  }[];
};
export const EMPTY_ROLE_USAGE: RoleUsage = { shortcuts: [], contactRoles: [] };

export function savedRoleTitles(
  usage: RoleUsage,
  options?: {
    shortcuts?: readonly string[];
    replacingContactRole?: string | null;
  },
): string[] {
  return [
    ...(options?.shortcuts ?? usage.shortcuts),
    ...usage.contactRoles
      .filter(
        ({ title, count }) =>
          count >
          (options?.replacingContactRole &&
          normalizeRole(title) === normalizeRole(options.replacingContactRole)
            ? 1
            : 0),
      )
      .map(({ title }) => title),
  ];
}
